comments.suggestion_code:
  try {
    existing = await Bun.file(SHELL_GITIGNORE).text();
  } catch (err: any) {
    const code = err?.code;
    if (code !== "ENOENT" && code !== "NotFound") {
      process.stderr.write(`ignore-shell: warning: could not read ${SHELL_GITIGNORE} (${code ?? "unknown"}): ${err instanceof Error ? err.message : String(err)}
`);
    }
    existing = "";
  }

comments.existing_code:
try {
  existing = await Bun.file(SHELL_GITIGNORE).text();
} catch {
  existing = "";
}
